import sys
sys.path.append('storage/zetetic')
from typing import Any, Dict, Sequence
from sota_hybrid import SotaHybridV4

def _define_hyperparameters():
    return {
        'learning_rate': 0.001,
        'dropout_rate': 0.1,
        'kernel_size': 7,
        'dilations': [1, 2, 4, 8, 16],
        'num_transformer_layers': 2,
        'num_heads': 4,
        'embed_dim': 256, # Increased to match SOTA
        'motif_kernel_size': 5
    }

class ModelWrapper:
    def __init__(self, **kwargs): self.network = SotaHybridV4(**kwargs)
    def init(self, rk, di):
        from jax import random
        pk, dk = random.split(rk)
        return self.network.init({'params': pk, 'dropout': dk}, di, deterministic=True)['params']
    def apply(self, p, x, d=True, rk=None):
        from jax import random
        if rk is None: rk = random.PRKey(0)
        return self.network.apply({'params': p}, x, deterministic=d, rngs={'dropout': rk})

def create_network(hparams: Dict[str, Any]):
    return ModelWrapper(
        d_output=hparams.get("d_output"), task_type=hparams.get("task_type"),
        kernel_size=hparams.get("kernel_size"), dilations=hparams.get("dilations"),
        num_transformer_layers=hparams.get("num_transformer_layers"), num_heads=hparams.get("num_heads"),
        dropout_rate=hparams.get("dropout_rate"), embed_dim=hparams.get("embed_dim"),
        motif_kernel_size=hparams.get("motif_kernel_size")
    )

